import unittest
from orders import summarize_orders as f
H='sku,quantity,unit_price,status\n'
class HiddenTests(unittest.TestCase):
    def test_empty(self):
        for text in ['', '  \n\t', H]:
            with self.subTest(text=text): self.assertEqual(f(text), [])
    def test_headers(self):
        with self.assertRaises(ValueError): f('sku,quantity\nA,1\n')
    def test_reordered_extra_headers(self):
        self.assertEqual(f('status,unit_price,extra,quantity,sku\nopen,1.25,x,2, a \n'),
                         [{'sku':'A','quantity':2,'total':'2.50'}])
    def test_mixed_prices_and_zero(self):
        self.assertEqual(f(H+'z,0,1,open\na,2,0.10,open\n A ,3,0.20,open\n'),
                         [{'sku':'A','quantity':5,'total':'0.80'}, {'sku':'Z','quantity':0,'total':'0.00'}])
    def test_cancelled_malformed_row(self):
        self.assertEqual(f(H+',bad,NaN, CaNcElLeD \nA,1,1.00,open\n'),
                         [{'sku':'A','quantity':1,'total':'1.00'}])
    def test_invalid_quantity(self):
        for q in ['-1','1.0','+1','1e2','abc','', '١']:
            with self.subTest(q=q), self.assertRaises(ValueError): f(H+f'A,{q},1,open\n')
    def test_invalid_price(self):
        for p in ['-1','NaN','Infinity','1.234','1e2','', '.50','1.']:
            with self.subTest(p=p), self.assertRaises(ValueError): f(H+f'A,1,{p},open\n')
    def test_blank_sku(self):
        with self.assertRaises(ValueError): f(H+' ,1,1,open\n')
    def test_error_line(self):
        with self.assertRaisesRegex(ValueError, r'3'):
            f(H+'A,1,1,open\nB,1,no,open\n')
    def test_spaces_leading_zeroes(self):
        self.assertEqual(f(H+' a , 002 , 01.20 ,open\n'),
                         [{'sku':'A','quantity':2,'total':'2.40'}])
