import json
from pathlib import Path
import subprocess
import tempfile
import unittest

class VisibleTests(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)
        self.db = str(Path(self.tmp.name) / 'tasks.sqlite3')

    def call(self, *args):
        r = subprocess.run(['python3', '-m', 'tasklist', '--db', self.db, *args], capture_output=True, text=True)
        self.assertEqual(r.returncode, 0, r.stderr)
        return json.loads(r.stdout)

    def test_fresh_list(self):
        self.assertEqual(self.call('list'), [])

    def test_add_persists(self):
        item = {'id': 1, 'title': 'Test task', 'done': False}
        self.assertEqual(self.call('add', ' Test task '), item)
        self.assertEqual(self.call('list'), [item])

    def test_done(self):
        self.call('add', 'Review')
        self.assertEqual(self.call('done', '1'), {'id': 1, 'title': 'Review', 'done': True})
        self.assertEqual(self.call('list'), [])
        self.assertEqual(len(self.call('list', '--all')), 1)
